    def __init__(self, N):
        self.N = N
        self.graph = [[] for _ in range(N)]

    def add_edge(self, fr, to, cap):
        forward = [to, cap, None]
        backward = [fr, 0, None]
        forward[2] = backward
        backward[2] = forward
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs_level(self, s, t, level):
        queue = deque()
        level[:] = [-1]*self.N
        level[s] = 0
        queue.append(s)
        while queue:
            v = queue.popleft()
            for edge in self.graph[v]:
                if edge[1] > 0 and level[edge[0]] < 0:
                    level[edge[0]] = level[v] + 1
                    queue.append(edge[0])
                    if edge[0] == t:
                        return
        return

    def dfs_flow(self, v, t, upTo, iter_, level):
        if v == t:
            return upTo
        for i in range(iter_[v], len(self.graph[v])):
            edge = self.graph[v][i]
            if edge[1] > 0 and level[v] < level[edge[0]]:
                d = self.dfs_flow(edge[0], t, min(upTo, edge[1]), iter_, level)
                if d > 0:
                    edge[1] -= d
                    reverse_edge = edge[2]
                    reverse_edge[1] += d
                    return d
            iter_[v] += 1
        return 0

